add(4,head('04-1｜歴史でたどる','同じ金利の変化でも、背景は違う。')+'''<div class="cards scenes"><button class="scene-card" data-scene="1" aria-pressed="false"><small>物価が上がるとき</small><h3>物価を抑えたい</h3><p>金融引締めと、<br>企業の利益への影響を追う。</p></button><button class="scene-card" data-scene="2" aria-pressed="false"><small>景気が弱るとき</small><h3>景気を支えたい</h3><p>金融緩和と、<br>先行きへの不安を分けて見る。</p></button><button class="scene-card" data-scene="3" aria-pressed="false"><small>期待が先に動くとき</small><h3>発表前から織り込む</h3><p>金利の水準だけでなく、<br>予想との違いを確かめる。</p></button></div><div class="seq" id="seq"><small id="seq-title">場面を選ぶと、何が先に起きるかが順に出ます。</small><div class="seq-row" id="seq-row"></div><div class="seq-ex" id="seq-ex"></div></div>''','scenes-page')
add(4,head('04-2｜物価が上がるとき','2022年、利上げは1年半続いた。')+'''<div class="chart"><div class="legend"><span class="gold">政策金利（米・実効FF金利）</span><span class="teal">株価（S&amp;P500・月末）</span></div>'''+series_chart('系列_2022利上げ.json',3400,4900,(3500,4000,4500),[(14,'fedfunds','2022年3月 利上げ開始',-16,-16,'end'),(21,'sp500_month_end','2022年10月 株価の底',18,8,'start'),(30,'fedfunds','2023年7月 最後の利上げ',0,-22,'middle')])+'''</div><div class="chart-notes"><div><small>物価</small><p>前年比7〜9%まで上昇。<br>抑えるための利上げだった。</p></div><div><small>株価</small><p>利上げの前から下がり始め、<br>利上げが続く途中で戻り始めた。</p></div><div><small>見方</small><p>金利の水準だけでなく、<br>「いつ止まるか」の予想が値段に入る。</p></div></div><p class="fine">出典：FRED（FEDFUNDS, SP500, CPIAUCSL）。月次、2021〜2023年。株価の動きには企業利益や期待の変化も関わる。</p>''','history')
add(4,head('04-3｜期待が先に動くとき','2024年、利下げは予想され、株価は先に動いた。')+'''<div class="chart"><div class="legend"><span class="gold">政策金利（米・実効FF金利）</span><span class="teal">株価（S&amp;P500・月末）</span></div>'''+series_chart('系列_2024利下げ.json',4500,7000,(5000,6000,7000),[(8,'fedfunds','2024年9月 利下げ開始',-16,32,'end'),(15,'sp500_month_end','2025年4月 関税不安で下落',18,26,'start'),(20,'fedfunds','2025年9月 利下げ再開',-16,32,'end')])+'''</div><div class="chart-notes"><div><small>物価</small><p>3%前後まで落ち着き、<br>利下げの余地ができた。</p></div><div><small>株価</small><p>利下げの前から上がり、後も続いた。<br>2025年春の下げは、関税不安が主因。</p></div><div><small>見方</small><p>「利下げなら株高」とも限らない。<br>理由が景気の弱さなら、話は別。</p></div></div><p class="fine">出典：FRED（FEDFUNDS, SP500, CPIAUCSL）。月次、2024〜2025年。株価の動きには企業利益や期待の変化も関わる。</p>''','history')
add(5,head('05｜ニュースで見ておきたい','まずは、3つの数字をつなぐ。')+cards([('01','政策金利','中央銀行は、<br>どう動こうとしているか。'),('02','長期金利','市場は、先の景気や物価を<br>どう見ているか。'),('03','物価上昇率','お金の購買力は、<br>どう変わっているか。')]),'numbers')
add(5,head('総まとめ｜第1回から第5回へ','ニュースを、一本のつながりで読む。')+'''<div class="final-map"><span>経済の変化</span><i>→</i><span>企業の利益</span><i>→</i><span>将来への期待</span><i>→</i><span>売り買いと価格</span></div><div class="final-anchor">金利という、もう一つの軸。</div><p class="lead">何が変わったのか。誰に影響するのか。<br>その期待は、すでに値段に入っているのか。</p>''','summary')
add(5,'<div class="city finale"></div><svg class="currents finale" viewBox="0 0 1440 810" aria-hidden="true"><path d="M1095 840C1120 640 1180 420 1268 246"/><path d="M1105 840C1135 660 1195 440 1270 248"/><path class="teal" d="M690 322C850 430 1000 560 1120 840"/><path d="M1440 600C1370 470 1315 340 1270 246"/></svg><div class="dawn-glow"></div><div class="hero-copy final"><small>明日、ニュースを開いたら</small>数字の向こうの、<br><em>お金の動きを見よう。</em><p>5回分の視点が、ここでひとつにつながる。</p></div>','scene ending')
